INSERT INTO `app_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES
('global', '{\"appName\":\"PPDI KABUPATEN BANDUNG\",\"appSubtitle\":\"SISTEM INFORMASI DATABASE & E-KTA PERANGKAT DESA\",\"logoUrl\":\"/logo_kabupaten_bandung.svg\",\"watermarkLogoUrl\":\"\",\"watermarkOpacity\":0.09,\"watermarkOpacityFront\":0.09,\"watermarkOpacityBack\":0.09,\"loginBackgroundType\":\"custom_image\",\"loginBackgroundImage\":\"data:image/jpeg;base64,\",\"loginOverlayOpacity\":\"0.55\",\"syncIntervalSeconds\":60,\"chairman_name\":\"DADANG IYAS, S.IP\",\"chairman_title\":\"Ketua Pengurus Daerah PPDI Kabupaten Bandung\",\"chairman_photo\":\"/uploads/chairman/chairman_1795274153057_f37b0b05.jpg\",\"chairman_greeting\":\"Assalamu’alaikum Warahmatullahi Wabarakatuh.\\n\\nSampurasun, Salam Satu Komando!\\n\\nRekan-rekan Perangkat Desa se-Kabupaten Bandung yang saya hormati dan saya banggakan,\\n\\nSelamat datang di portal resmi Sistem Informasi Database & E-KTA PPDI Kabupaten Bandung (anggota.ppdibandungkab.or.id).\\n\\nPerjuangan kita tidak pernah berjalan sendiri—kekuatan kita lahir dari barisan yang solid, terdata rapi, dan saling menguatkan dari desa hingga kabupaten. Kehadiran sistem database terpadu dan E-KTA ini bukan sekadar pembaruan administrasi, melainkan penanda identitas bersama bahwa kita adalah satu kesatuan perjuangan yang memperjuangkan marwah, kepastian hak, dan kesejahteraan perangkat desa.\\n\\nMari kita lengkapi dan mutakhirkan data kita bersama sebagai bukti kesolidan organisasi. Dengan data yang kuat dan valid, langkah perjuangan PPDI Kabupaten Bandung akan semakin terukur, bermartabat, dan berdampak nyata.\\n\\nWassalamu’alaikum Warahmatullahi Wabarakatuh.\\n\\nSemangat Perjuangan Bersama, Perangkat Desa Jaya!\\nCing Sarehat, CIng Garede Milik, Yow!!!\",\"rolePermissions\":{\"Superadmin_Kabupaten\":{\"dashboard\":{\"view\":true,\"add\":true,\"edit\":true,\"delete\":true},\"pendaftaran\":{\"view\":true,\"add\":true,\"edit\":true,\"delete\":true},\"anggota\":{\"view\":true,\"add\":true,\"edit\":true,\"delete\":true},\"ekta\":{\"view\"