DROP TABLE IF EXISTS `anggota`;
CREATE TABLE `anggota` (
  `id_anggota` int(11) NOT NULL AUTO_INCREMENT,
  `nik` varchar(16) NOT NULL COMMENT '16 digit NIK KTP',
  `nipd` varchar(28) NOT NULL COMMENT 'Nomor Induk Perangkat Desa',
  `nama_lengkap` varchar(150) NOT NULL,
  `gelar_depan` varchar(30) DEFAULT NULL,
  `gelar_belakang` varchar(50) DEFAULT NULL,
  `tempat_lahir` varchar(100) NOT NULL,
  `tanggal_lahir` date NOT NULL COMMENT 'Dasar kalkulasi pensiun 60 tahun',
  `jenis_kelamin` enum('L','P') NOT NULL,
  `agama` varchar(30) NOT NULL DEFAULT 'Islam',
  `pendidikan_terakhir` enum('SMA/SMK','D1','D2','D3','S1','S2','S3') NOT NULL,
  `no_hp_wa` varchar(20) NOT NULL COMMENT 'Nomor WA aktif untuk notifikasi',
  `email` varchar(100) DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `alamat_rumah` text NOT NULL,
  `status_pernikahan` enum('Kawin','Belum Kawin','Cerai Hidup','Cerai Mati') NOT NULL DEFAULT 'Kawin',
  `kode_kecamatan` varchar(10) DEFAULT NULL,
  `nomor_urut` int(11) DEFAULT NULL,
  `no_kta` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_anggota`,`nik`,`nipd`) USING BTREE,
  UNIQUE KEY `uq_anggota_nik` (`nik`),
  UNIQUE KEY `uq_anggota_no_kta` (`no_kta`),
  KEY `idx_anggota_tgl_lahir` (`tanggal_lahir`),
  KEY `idx_anggota_nama` (`nama_lengkap`),
  KEY `idx_anggota_hp` (`no_hp_wa`),
  KEY `idx_anggota_kecamatan_urut` (`kode_kecamatan`,`nomor_urut`)
) ENGINE=InnoDB AUTO_INCREMENT=689 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


